async function openItem(id,task=null){opened=await call('open',{id,...(task?{task}:{})});opened.task=task;page=opened.progress.page||0;question=0;feedback=null;if(id==='reading-check'){if(opened.progress.complete){toast('Reading check already completed. Your teacher can see your result.');return}assessmentAnswers=opened.progress.answers||{};section=Math.min(4,Math.floor(Object.keys(assessmentAnswers).length/10));view='test'}else if(id.startsWith('novel-')||id.startsWith('reader-')||id.startsWith('college-')||opened.content.pagesCount){service='reader';opened.pageText=(await call('page',{id,page})).text;view='read'}else{service='maths';view='quiz'}render()}
function goto(v){if(v==='advent'){view='advent';opened=null;run(async()=>{advent=await call('advent_status');render()});return}if(v==='annual'){view='annual';opened=null;annualQuestion=0;run(async()=>{annual=await call('annual_open');annualQuestion=annual.eligible?Math.min(Object.keys(annual.answers||{}).length,annual.questions.length-1):0;render()});return}if(v==='portal'){location.href=link('OneHome');return}if(v==='reader'||v==='maths'){const target=v==='reader'?'OneReader':'OneMaths';if(product!==target){location.href=link(target);return}}by('toast').classList.remove('show');if(v==='reader'||v==='maths'){service=v;view='service'}else view=v;search='';filter='';opened=null;feedback=null;run(refresh)}
