 by('csvText')?.addEventListener('input',()=>{imported=null;by('confirmImport').disabled=true});by('previewImport')?.addEventListener('click',()=>run(async()=>{imported=importRows(by('csvText').value);by('importPreview').innerHTML=`<p>${imported.length} rows ready. Review the first 10:</p>`+table(['Name','Year','Class','ID'],imported.slice(0,10).map(r=>[esc(r.first+' '+r.last),r.year,esc(r.class),esc(r.externalId)]));by('confirmImport').disabled=false}));
