 by('answerForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{feedback=await call('answer',{id:opened.id,question,answer:Number(new FormData(e.target).get('answer')),...(opened.task?{task:opened.task}:{})});opened.progress=feedback.progress;render();if(feedback.correct)celebrate()},e.submitter)});by('prevQuestion')?.addEventListener('click',()=>{question--;feedback=null;render()});by('nextQuestion')?.addEventListener('click',()=>run(async()=>{if(service==='reader'&&(!opened.content.questions[question+1]||opened.content.questions[question+1].checkpoint!==opened.content.questions[question].checkpoint)){if(page<(opened.content.pagesCount||5)-1){const next=page+1;opened.pageText=(await call('page',{id:opened.id,page:next})).text;page=next;view='read'}else{goto('library');return}}else if(question===opened.content.questions.length-1){goto('homework');return}else question++;feedback=null;render()}));
 function collectTest(){const f=new FormData(by('testForm'));for(const [k,v] of f)assessmentAnswers[k.slice(1)]=Number(v)}
