function bindSignIn(){const checkSchool=()=>{const schoolValue=new FormData(by('signin')).get('school');if(!schoolValue||schoolValue!==slug){sessionStorage.setItem('onehome-mode','student');location.href='?school='+encodeURIComponent(schoolValue||'');return false}return true};for(const [id,provider] of [['microsoftLogin','azure'],['googleLogin','google']])by(id)?.addEventListener('click',e=>run(async()=>{if(checkSchool())await oauth(provider)},e.currentTarget));by('emailLogin')?.addEventListener('click',e=>run(async()=>{if(!checkSchool())return;await emailCode(by('studentEmail').value.trim());toast('Check your school inbox for the sign-in code.')},e.currentTarget));by('verifyEmail')?.addEventListener('click',e=>run(async()=>{if(!checkSchool())return;await verifyEmail(by('studentEmail').value.trim(),by('emailToken').value.trim());mode='student';code='';state=null;await refresh()},e.currentTarget))}
for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,()=>lastActivity=Date.now(),{passive:true});
setInterval(()=>{if(student()&&opened&&!document.hidden&&!paused&&Date.now()-lastActivity<60000&&['read','quiz'].includes(view))call('tick',{id:opened.id,task:opened.task||undefined,seconds:15}).catch(()=>{})},15000);

async function assetContent(doc){if(!doc?.asset)return doc;if(!/^content-[a-zA-Z0-9-]+\.json$/.test(doc.asset))throw Error('Invalid content file.');const key=doc.asset+doc.assetHash;if(!assetCache.has(key)){const buffer=await bundledContent(doc.asset);const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))).map(n=>n.toString(16).padStart(2,'0')).join('');if(hash!==doc.assetHash)throw Error('Website content and SQL versions do not match. Upload the latest website files and run the matching SQL.');assetCache.set(key,JSON.parse(new TextDecoder().decode(buffer)))}const publicData=assetCache.get(key);return {...publicData,...doc,pages:publicData.pages,questions:publicData.questions.map((q,i)=>({...q,...doc.questions?.[i]}))}}
async function enrich(action,res){if(res?.content)res.content=await assetContent(res.content);if(action==='page'&&res.asset){const d=await assetContent(res);res.text=d.pages[res.page]}if(action.startsWith('annual_')&&res.questions)res.questions=await Promise.all(res.questions.map(async q=>{const d=await assetContent(q);return {...q,questionData:q.asset?d.questions[q.question]:q.questionData}}));return res}
function buddyOn(){return student()&&state.settings.buddy!==false}
function buddyName(){return wallet?.name||'Pip'}
function buddyLayers(only=null){const selected=only?[only]:Object.values(wallet?.equipped||{}).map(id=>rewards.find(r=>r.id===id)).filter(r=>r?.image);return `<div class="buddy-drawing"><img src="buddies.svg#${esc(wallet?.buddy||'fox')}" alt="${esc(buddyName())}, your study buddy">${selected.map(r=>`<img class="outfit-layer" src="${esc(r.image)}" alt="${esc(r.name)}">`).join('')}</div>`}
function petCard(){if(!buddyOn())return '';const fed=Date.now()-new Date(wallet?.fed||0).getTime()<86400000,water=Date.now()-new Date(wallet?.water||0).getTime()<86400000;return `<section class="card pet-card">${buddyLayers()}<div><span class="eyebrow">Your study buddy</span><h2>${esc(buddyName())}</h2><p>${fed&&water?'Ready to help with maths and reading.':'A meal and a drink recharge your buddy’s bonus hints.'}</p><div class="toolbar space"><button data-care="fed" class="secondary" ${fed?'disabled':''}>${fed?'Fed today':'Food · 5 Power Points'}</button><button data-care="water" class="secondary" ${water?'disabled':''}>${water?'Water topped up':'Water · 5 Power Points'}</button></div><small>Each lasts 24 hours. Normal hints always stay free.</small><button class="quiet space" data-view="wardrobe">Name & outfits</button>${view==='quiz'?'<button id="petHelp" class="secondary space">Ask my buddy for a hint</button>':view==='read'?'<button id="readingBuddy" class="secondary space">Help me read this page</button>':''}</div></section>`}
function wardrobe(){if(!buddyOn())return heading('Study buddy is switched off','Your school controls this feature.');return heading('Make your buddy your own','Choose a name and mix the clothes you own.')+`<div class="grid">${petCard()}<form id="buddyNameForm" class="card"><h2>A name for your companion</h2><label>Buddy’s name<input name="name" value="${esc(buddyName())}" maxlength="24" required></label><button>Save name</button></form></div><div class="book-grid space">${rewards.filter(r=>r.image&&wallet?.owned?.includes(r.id)).map(r=>`<article class="card">${buddyLayers(r)}<h3>${esc(r.name)}</h3><button class="secondary" data-outfit="${r.id}" data-remove="${Object.values(wallet?.equipped||{}).includes(r.id)}">${Object.values(wallet?.equipped||{}).includes(r.id)?'Take off':'Put on'}</button></article>`).join('')||'<p>No outfits yet. Visit the reward shop to choose one.</p>'}</div>`}
function annualPage(){if(!annual)return heading('Your yearly book review','Loading your review…');if(!annual.eligible)return heading('Your yearly book review','Finish a book and its check-ins to unlock your review. You can take one review each school year.');if(annual.complete)return heading('Your yearly review is complete',`${annual.year}–${annual.year+1} · ${annual.score}/${annual.questions.length} correct · ${annual.points} Star Points earned. Your next review opens in September.`);const i=annualQuestion,q=annual.questions[i],answered=annual.answers?.[i]!==undefined;return heading('Your yearly book review',`${annual.year}–${annual.year+1} · Question ${i+1} of ${annual.questions.length}`)+`<section class="card assessment"><span class="badge">${esc(q.title)}</span><p class="space">Based on books you have completed. Your first answer is saved; bonus hints are paused during this review.</p><h2 class="space">${esc(q.questionData.prompt)}</h2><form id="annualAnswer"><div class="choices">${q.questionData.choices.map((a,j)=>`<label><input type="radio" name="answer" value="${j}" ${answered?'disabled':''} ${annual.answers?.[i]===j?'checked':''} required>${esc(a)}</label>`).join('')}</div>${answered?'<button type="button" id="annualNext">Next question</button>':'<button>Save answer</button>'}</form></section>`}
function bookUploadPage(){return heading('Add a book for your school','Upload a plain-text book you have permission to share. Your school’s books remain private to your school.')+`<form id="bookUploadForm" class="card"><div class="form-grid"><label>Title<input name="title" maxlength="150" required></label><label>Author<input name="author" maxlength="120" required></label><label>Suggested age group<select name="age"><option>11–13</option><option>13–15</option><option>15–16</option></select></label><label>Plain-text book (.txt, up to 600 KB)<input type="file" id="newBookFile" accept=".txt,text/plain" required></label></div><label><input type="checkbox" name="gothic">Gothic / mature themes — school approval and Years 10–11 only</label><label class="space"><input type="checkbox" name="rights" required>I have permission to share this text, or have checked that it is public domain.</label><button type="button" id="prepareBook" class="secondary space">Prepare pages & questions</button><p class="space">We make two text-recall questions for each five-page block. Review and edit the questions below before publishing. These are not a validated reading-age measure.</p><div id="bookDraft" class="space"></div><button id="publishBook" class="space" disabled>Publish to this school</button></form>`}
function prepareBook(text){const paragraphs=text.replace(/\r/g,'').split(/\n\s*\n/).map(p=>p.replace(/\s+/g,' ').trim()).filter(Boolean);const words=paragraphs.join('\n\n').split(/\s+/);if(words.length<150)throw Error('Add at least 150 words of book text.');const pages=[];let page=[];for(const p of paragraphs){if(p.split(' ').length>400){if(page.length){pages.push(page.join('\n\n'));page=[]}const w=p.split(' ');for(let i=0;i<w.length;i+=220)pages.push(w.slice(i,i+220).join(' '))}else{page.push(p);if(page.join(' ').split(' ').length>=220){pages.push(page.join('\n\n'));page=[]}}}if(page.length)pages.push(page.join('\n\n'));const questions=[];for(let end=4;end<pages.length+4;end+=5){const last=Math.min(end,pages.length-1),block=pages.slice(Math.max(0,last-4),last+1).join(' '),sentences=block.match(/[^.!?]+[.!?]+/g)||[block];const usable=sentences.filter(s=>s.split(' ').length>=10&&s.split(' ').length<50);for(let n=0;n<2;n++){const sentence=(usable[n%Math.max(1,usable.length)]||block.slice(0,240)).trim();const words=[...new Set(sentence.match(/[A-Za-z]{5,}/g)||[])];const answer=words[n%Math.max(words.length,1)]||'word';let wrong=[...words.filter(w=>w!==answer),'window','journey','garden','morning'].filter(w=>w!==answer);wrong=[...new Set(wrong)].slice(0,3);questions.push({prompt:'Which word completes this line from the text? “'+sentence.replace(answer,'____')+'”',choices:[answer,...wrong],correct:0,hint:'Return to the relevant pages and compare the original wording.',pageEnd:last,checkpoint:Math.floor(last/5)})}}return {pages,questions,pagesCount:pages.length,wordCount:words.length,long:true}}
function bindNew(){by('buddyNameForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{wallet=await call('buddy_name',{name:new FormData(e.target).get('name')});render();toast('Buddy name saved.')},e.submitter)});document.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>run(async()=>{wallet=await call('equip',{reward:b.dataset.outfit,remove:b.dataset.remove==='true'});render()},b));
 by('readingBuddy')?.addEventListener('click',()=>{const words=(opened.pageText||'').split(/\s+/).length;toast(`${buddyName()}: This page has about ${words} words. Read one paragraph at a time, pause, and say what happened in your own words. Use the reading guide or a larger font if that helps.`)});
 by('annualAnswer')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{annual=await call('annual_answer',{question:annualQuestion,answer:Number(new FormData(e.target).get('answer'))});render()},e.submitter)});by('annualNext')?.addEventListener('click',()=>{annualQuestion=Math.min(annualQuestion+1,annual.questions.length-1);render()});
 by('prepareBook')?.addEventListener('click',e=>run(async()=>{const f=by('newBookFile').files[0];if(!f)throw Error('Choose a text file.');if(f.size>600000)throw Error('Use a text file under 600 KB.');bookDraft=prepareBook(await f.text());by('bookDraft').innerHTML=`<h2>${bookDraft.pages.length} pages · ${bookDraft.questions.length} questions</h2><div class="task-items">${bookDraft.questions.map((q,i)=>`<details><summary>Checkpoint ${q.checkpoint+1} · question ${i%2+1}</summary><label>Question<textarea data-prompt="${i}">${esc(q.prompt)}</textarea></label>${q.choices.map((a,j)=>`<label>Answer ${j+1}<input data-choice="${i}-${j}" value="${esc(a)}"></label>`).join('')}<label>Correct choice<select data-correct="${i}">${[0,1,2,3].map(j=>`<option value="${j}">${j+1}</option>`).join('')}</select></label><p>${esc(bookDraft.pages[q.pageEnd])}</p></details>`).join('')}</div>`;by('publishBook').disabled=false},e.currentTarget));
 by('newBookFile')?.addEventListener('change',()=>{bookDraft=null;by('publishBook').disabled=true;by('bookDraft').innerHTML=''});
 by('bookUploadForm')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{if(!bookDraft)throw Error('Prepare and review the book first.');const f=new FormData(e.target);for(let i=0;i<bookDraft.questions.length;i++){const q=bookDraft.questions[i];q.prompt=document.querySelector(`[data-prompt="${i}"]`).value;q.choices=q.choices.map((a,j)=>document.querySelector(`[data-choice="${i}-${j}"]`).value);q.correct=Number(document.querySelector(`[data-correct="${i}"]`).value)}await call('book_upload',{rights:f.has('rights'),book:{...bookDraft,title:f.get('title'),author:f.get('author'),age:f.get('age'),gothic:f.has('gothic'),genre:'School library'}});bookDraft=null;view='library';await refresh();toast('Your school book is ready.')},e.submitter)});
}
